# Now generate text
content_lines = [header]

for s_num in range(1, 115):
    if s_num in surahs_asbab:
        s_data = surahs_asbab[s_num]
        content_lines.append(f"\n{s_data['name']}\n")
        for entry in s_data["entries"]:
            content_lines.append(entry["text"] + "\n")

full_content = "\n".join(content_lines)

# Write to src/data/al_muharar_asbab.txt
out_txt = "src/data/al_muharar_asbab.txt"
with open(out_txt, "w", encoding="utf-8") as f:
    f.write(full_content)
print(f"Wrote {len(full_content)} chars to {out_txt}")

# Write to src/data/muharrarAsbabData.ts
out_ts = "src/data/muharrarAsbabData.ts"
escaped_content = json.dumps(full_content, ensure_ascii=False)
with open(out_ts, "w", encoding="utf-8") as f:
    f.write(f"export const muharrarAsbabRaw = {escaped_content};\n")
print(f"Wrote TS export to {out_ts}")
